// Exact id / instance first, then a name match. Lists the names when unsure.
const q = String($('Edit a Business').first().json.query || '').trim().toLowerCase();
const all = $input.all().map((i) => i.json).filter((c) => c && c.client_id);
const norm = (s) => String(s || '').trim().toLowerCase();
let hits = all.filter((c) => norm(c.client_id) === q || norm(c.instance_name) === q || norm(c.business_name) === q);
if (!hits.length) hits = all.filter((c) => norm(c.business_name).includes(q));
if (hits.length === 1) return [{ json: { found: true, client: hits[0] } }];
const names = (hits.length ? hits : all).map((c) => c.business_name + ' (' + c.client_id + ')').slice(0, 40);
return [{ json: { found: false, reason: hits.length ? 'More than one business matches.' : 'No business matches that.', names } }];

// The edit page, filled with what the business has today.
const c = $('Find Business').first().json.client;
const products = $input.all().map((i) => i.json).filter((p) => p && p.item_name)
  .sort((a, b) => String(a.item_name).localeCompare(String(b.item_name)));
const line = (p) => [p.item_name, p.price ?? '', p.quantity ?? '', p.payment_url || '', p.description || ''].join(' | ');
let nums = c.alert_numbers;
if (typeof nums === 'string') nums = nums.replace(/[{}]/g, '').split(',');
const fields = [
  { fieldLabel: 'Products — one per line: Name | price | stock | payment link | description. Edit a line to change it, add a line to add a product, delete a line to remove it.', fieldName: 'products', fieldType: 'textarea', defaultValue: products.map(line).join('\n') },
  { fieldLabel: 'Business name', fieldName: 'business_name', fieldType: 'text', requiredField: true, defaultValue: c.business_name || '' },
  { fieldLabel: 'Owner / staff WhatsApp numbers for alerts', fieldName: 'alert_numbers', fieldType: 'text', requiredField: true, defaultValue: (nums || []).join(', ') },
  { fieldLabel: 'Alert email', fieldName: 'alert_email', fieldType: 'text', defaultValue: c.alert_email || '' },
  { fieldLabel: 'Tagline', fieldName: 'tagline', fieldType: 'text', defaultValue: c.tagline || '' },
  { fieldLabel: 'Website', fieldName: 'website', fieldType: 'text', defaultValue: c.website || '' },
  { fieldLabel: 'What the business does', fieldName: 'about', fieldType: 'textarea', defaultValue: c.about || '' },
  { fieldLabel: 'Key info & FAQs (hours, delivery, how to pay…)', fieldName: 'faqs', fieldType: 'textarea', defaultValue: c.faqs || '' },
  { fieldLabel: 'Tone', fieldName: 'tone', fieldType: 'text', defaultValue: c.tone || '' },
  { fieldLabel: 'Currency', fieldName: 'currency', fieldType: 'text', defaultValue: c.currency || 'NGN' },
  { fieldLabel: 'Bot status', fieldName: 'status', fieldType: 'dropdown', defaultValue: c.active === false ? 'Paused' : 'Active', fieldOptions: { values: [{ option: 'Active' }, { option: 'Paused' }] } },
];
return [{ json: { fields: JSON.stringify(fields), title: 'Edit ' + (c.business_name || c.client_id) } }];

// Turns the edited page into database changes: one update for the business,
// and a create / update / delete for each product that changed.
const f = $input.first().json;
const v = (k, label) => (f[k] !== undefined ? f[k] : f[label]);
const c = $('Find Business').first().json.client;
const old = $('Get Products').all().map((i) => i.json).filter((p) => p && p.item_name);
const byName = new Map(old.map((p) => [String(p.item_name).trim().toLowerCase(), p]));
const num = (s) => { const n = Number(String(s ?? '').replace(/[^0-9.]/g, '')); return String(s ?? '').trim() === '' || isNaN(n) ? null : n; };
const ops = [];
const numbers = String(v('alert_numbers') || '').split(/[,;\s]+/).map((n) => n.replace(/\D/g, '').replace(/^0(\d{10})$/, '234$1')).filter((n) => n.length >= 8);
ops.push({ op: 'client', id: c.id, business_name: String(v('business_name') || c.business_name).trim(), alert_numbers: '{' + numbers.join(',') + '}', alert_email: String(v('alert_email') || '').trim(), tagline: String(v('tagline') || '').trim(), website: String(v('website') || '').trim(), about: String(v('about') || '').trim(), faqs: String(v('faqs') || '').trim(), tone: String(v('tone') || '').trim(), currency: (String(v('currency') || 'NGN').trim() || 'NGN').toUpperCase(), active: v('status') !== 'Paused' });
const seen = new Set();
const skipped = [];
for (const raw of String(v('products') || '').split('\n').map((l) => l.trim()).filter(Boolean)) {
  const [name, price, stock, link, desc] = raw.split('|').map((x) => (x ?? '').trim());
  if (!name) continue;
  const key = name.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const was = byName.get(key);
  const row = {
    item_name: name,
    price: num(price) ?? (was ? Number(was.price) || 0 : null),
    quantity: num(stock) ?? (was ? Number(was.quantity) || 0 : 100),
    payment_url: /^https?:\/\//.test(link || '') ? link : '',
    description: desc || '',
  };
  if (!was) {
    if (row.price === null) { skipped.push(name + ' (no price)'); continue; }
    ops.push({ op: 'create', client_id: c.client_id, ...row });
  } else if (String(was.item_name) !== row.item_name || Number(was.price) !== row.price || Number(was.quantity) !== row.quantity || String(was.payment_url || '') !== row.payment_url || String(was.description || '') !== row.description) {
    ops.push({ op: 'update', id: was.id, ...row });
  }
}
for (const [key, p] of byName) if (!seen.has(key)) ops.push({ op: 'delete', id: p.id, item_name: p.item_name });
return ops.map((o) => ({ json: { ...o, skipped } }));

// What was changed, shown once everything above has been saved.
const ops = $('Plan Changes').all().map((i) => i.json);
const esc = (t) => String(t).replace(/[<>&]/g, '');
const b = ops.find((o) => o.op === 'client') || {};
const list = (op, verb) => ops.filter((o) => o.op === op).map((o) => '<li>' + verb + ' <b>' + esc(o.item_name) + '</b>' + (op !== 'delete' ? ' — ' + o.price + ' · stock ' + o.quantity : '') + '</li>').join('');
const items = list('create', 'Added') + list('update', 'Updated') + list('delete', 'Removed');
const skipped = (ops[0] && ops[0].skipped) || [];
return [{ json: { html: '<div style="font-family:system-ui,sans-serif;max-width:560px;margin:24px auto">'
  + '<h2>✅ ' + esc(b.business_name) + ' saved</h2>'
  + '<p>Bot is <b>' + (b.active ? 'active' : 'paused') + '</b>. Changes apply to the next WhatsApp message.</p>'
  + '<h3>Products</h3>' + (items ? '<ul>' + items + '</ul>' : '<p style="color:#666">No product changes.</p>')
  + (skipped.length ? '<p style="color:#b45309">Not added (a new product needs a price): ' + skipped.map(esc).join(', ') + '</p>' : '')
  + '</div>' } }];
